204	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
205	    @Override
206	    public ResponseEntity<PetDto> getOwnersPet(Integer ownerId, Integer petId) {
207	        Owner owner = this.clinicService.findOwnerById(ownerId);
208	        if (owner != null) {
209	            Pet pet = owner.getPet(petId);
