211	                return new ResponseEntity<>(petMapper.toPetDto(pet), HttpStatus.OK);
212	            }
213	        }
214	        return new ResponseEntity<>(HttpStatus.NOT_FOUND);
215	    }
216	
217	    /**
218	     * Applies the intake rules a newly submitted owner must satisfy before it is persisted.
219	     * The required fields are checked, the telephone and email are normalized in place, and
220	     * the resulting telephone is rejected when it already belongs to another owner. Each rule
221	     * signals a violation by throwing, which the exception advice renders as the matching 4xx
222	     * response; when the method returns normally {@code ownerFieldsDto} is normalized and ready
223	     * to be mapped and saved.
224	     *
225	     * @param ownerFieldsDto the submitted owner fields, normalized in place
226	     */
227	    private void prepareNewOwner(OwnerFieldsDto ownerFieldsDto) {
228	        validateRequiredFields(ownerFieldsDto);
229	        ownerFieldsDto.setTelephone(normalizeTelephone(ownerFieldsDto.getTelephone()));
230	        ownerFieldsDto.setEmail(normalizeEmail(ownerFieldsDto.getEmail()));
231	        rejectDuplicateTelephone(ownerFieldsDto.getTelephone());
232	        rejectDuplicateHousehold(ownerFieldsDto);
233	    }
234	
235	    /**
236	     * Builds the customer code assigned to a newly created owner. The code is formatted as
237	     * {@code '<LAST3>-<NNNN>'}, where {@code LAST3} is the upper-cased first three letters of
238	     * the owner's last name and {@code NNNN} is a global 4-digit zero-padded sequence equal to
239	     * one more than the current number of owners. For example the seventh owner named
240	     * {@code 'Smith'} is assigned {@code 'SMI-0007'}.
241	     *
242	     * @param lastName the owner's last name
243	     * @return the formatted customer code
244	     */
245	    private String nextCustomerCode(String lastName) {
246	        String last3 = lastName.substring(0, Math.min(3, lastName.length())).toUpperCase();
247	        long sequence = this.clinicService.findAllOwners().size() + 1L;
248	        return String.format("%s-%04d", last3, sequence);
249	    }
250	
251	    /**
252	     * Rejects an owner whose {@code firstName}, {@code lastName}, {@code address}, {@code city}
253	     * or {@code telephone} is missing or blank. A field that is only whitespace is treated as
254	     * blank. When any field fails, a {@link RequiredFieldsMissingException} is thrown carrying
255	     * the names of every offending field, which the exception advice renders as a 400 response
256	     * with an {@code errors} array.
257	     *
258	     * @param ownerFieldsDto the submitted owner fields
259	     */
260	    private void validateRequiredFields(OwnerFieldsDto ownerFieldsDto) {
261	        List<String> missing = new ArrayList<>();
262	        addIfBlank(missing, "firstName", ownerFieldsDto.getFirstName());
263	        addIfBlank(missing, "lastName", ownerFieldsDto.getLastName());
264	        addIfBlank(missing, "address", ownerFieldsDto.getAddress());
265	        addIfBlank(missing, "city", ownerFieldsDto.getCity());
266	        addIfBlank(missing, "telephone", ownerFieldsDto.getTelephone());
267	        if (!missing.isEmpty()) {
268	            throw new RequiredFieldsMissingException(missing);
269	        }
270	    }
271	
272	    private void addIfBlank(List<String> missing, String fieldName, String value) {
273	        if (value == null || value.isBlank()) {
274	            missing.add(fieldName);
275	        }
276	    }
277	
278	    /**
279	     * Normalizes a submitted telephone number into E.164 form. Spaces, dashes and brackets
280	     * are stripped. When a leading {@code '+'} and country code are present they are kept as
281	     * given; otherwise the country code {@code '+61'} is assumed and a single leading
282	     * {@code '0'} is dropped from the national digits. The result must be a {@code '+'}
283	     * followed by 8 to 15 digits. The normalized E.164 value is what gets stored and returned.
284	     * When the value cannot form a valid E.164 number an {@link InvalidFieldsException} is
285	     * thrown, which the exception advice renders as a 400 response naming the {@code telephone}
286	     * field. For example {@code "0412 345 678"} becomes {@code "+61412345678"}.
287	     *
288	     * @param telephone the submitted telephone value
289	     * @return the normalized E.164 telephone
290	     */
291	    private String normalizeTelephone(String telephone) {
292	        String cleaned = telephone == null ? "" : telephone.replaceAll("[\\s\\-()]", "");
293	        String e164;
294	        if (cleaned.startsWith("+")) {
295	            e164 = "+" + cleaned.substring(1);
296	        } else {
297	            String national = cleaned;
298	            if (national.startsWith("0")) {
299	                national = national.substring(1);
300	            }
301	            e164 = "+61" + national;
302	        }
303	        if (!e164.matches("^\\+[0-9]{8,15}$")) {
304	            throw new InvalidFieldsException(List.of("telephone"));
305	        }
306	        return e164;
307	    }
308	
309	    /**
310	     * Pattern for a syntactically valid email address: a non-empty local part, an {@code @},
311	     * and a domain containing at least one dot, none of the parts holding whitespace or a
312	     * second {@code @}.
313	     */
314	    private static final java.util.regex.Pattern EMAIL_PATTERN =
315	        java.util.regex.Pattern.compile("^[^\\s@]+@[^\\s@]+\\.[^\\s@]+$");
316	
317	    /**
318	     * Normalizes an optional owner email. An email is optional, so a {@code null} value is
319	     * accepted and returned unchanged. When present it must be a syntactically valid address;
320	     * the value is stored and returned lower-cased. When present but invalid an
321	     * {@link InvalidFieldsException} is thrown, which the exception advice renders as a 400
322	     * response naming the {@code email} field.
323	     *
324	     * @param email the submitted email value, or {@code null} when omitted
325	     * @return the lower-cased email, or {@code null} when none was supplied
326	     */
327	    private String normalizeEmail(String email) {
328	        if (email == null) {
329	            return null;
330	        }
331	        String trimmed = email.trim();
332	        if (!EMAIL_PATTERN.matcher(trimmed).matches()) {
333	            throw new InvalidFieldsException(List.of("email"));
334	        }
335	        return trimmed.toLowerCase(java.util.Locale.ROOT);
336	    }
337	
338	    /**
339	     * Rejects a new owner whose normalized telephone is already used by any existing owner.
340	     * The telephone is stored in its normalized E.164 form, so a plain equality check
341	     * against every owner's telephone compares E.164 values. When a match is found a
342	     * {@link DuplicateTelephoneException} is thrown, which the exception advice renders as a
343	     * 409 Conflict response.
344	     *
345	     * @param telephone the normalized telephone of the owner being created
346	     */
347	    private void rejectDuplicateTelephone(String telephone) {
348	        boolean taken = this.clinicService.findAllOwners().stream()
349	            .anyMatch(existing -> telephone.equals(existing.getTelephone()));
350	        if (taken) {
351	            throw new DuplicateTelephoneException(telephone);
352	        }
353	    }
354	
355	    /**
356	     * Rejects a new owner whose {@code lastName} and {@code address} already belong to another
357	     * owner, i.e. one that shares its household (see {@link #findHouseholdMate(String, String)}
358	     * for how that identity is compared). A request may bypass this rule by setting
359	     * {@code sharesHousehold} to {@code true}, allowing several owners to share one household.
360	     * When a household mate is found and the request did not opt in a
361	     * {@link DuplicateHouseholdException} is thrown, which the exception advice renders as a 409
362	     * Conflict response.
363	     *
364	     * @param ownerFieldsDto the submitted owner fields
365	     */
366	    private void rejectDuplicateHousehold(OwnerFieldsDto ownerFieldsDto) {
367	        if (Boolean.TRUE.equals(ownerFieldsDto.getSharesHousehold())) {
368	            return;
369	        }
370	        boolean taken = findHouseholdMate(ownerFieldsDto.getLastName(), ownerFieldsDto.getAddress()).isPresent();
371	        if (taken) {
372	            throw new DuplicateHouseholdException(ownerFieldsDto.getLastName(), ownerFieldsDto.getAddress());
373	        }
374	    }
375	
376	    /**
377	     * Finds an existing owner that shares a household with the given {@code lastName} and
378	     * {@code address}. Both fields are compared case-insensitively and with runs of whitespace
379	     * collapsed to a single space (and surrounding whitespace trimmed), so for example
380	     * {@code "Franklin"} at {@code "110  W. Liberty St."} matches {@code "franklin"} at
381	     * {@code "110 W. Liberty St."}. When several owners match, the first one encountered is
382	     * returned. This is the single definition of household identity shared by every rule that
383	     * reasons about households.
384	     *
385	     * @param lastName the last name to match on
386	     * @param address the address to match on
387	     * @return the first owner sharing the household, or empty when none exists
388	     */
389	    private Optional<Owner> findHouseholdMate(String lastName, String address) {
390	        String normalizedLastName = collapseWhitespace(lastName);
391	        String normalizedAddress = collapseWhitespace(address);
392	        return this.clinicService.findAllOwners().stream()
393	            .filter(existing -> normalizedLastName.equalsIgnoreCase(collapseWhitespace(existing.getLastName()))
394	                && normalizedAddress.equalsIgnoreCase(collapseWhitespace(existing.getAddress())))
395	            .findFirst();
396	    }
397	
398	    /**
399	     * Collapses a field for household comparison: leading and trailing whitespace is trimmed and
400	     * every internal run of whitespace is reduced to a single space. A {@code null} value collapses
401	     * to the empty string. Case is left untouched so callers can compare case-insensitively.
402	     *
403	     * @param value the value to collapse, or {@code null}
404	     * @return the whitespace-collapsed value, never {@code null}
405	     */
406	    private String collapseWhitespace(String value) {
407	        if (value == null) {
408	            return "";
409	        }
410	        return value.trim().replaceAll("\\s+", " ");
411	    }
